// Buffer top-up (Part 2 §2.4): prefer the earliest planned fb_content_plan slot within
// GENERATION_BUFFER_DAYS that has no post yet; otherwise fall back to the first open date
// in a 5-day window so it never goes dark. Reads fb_content_plan + the chosen subtopic via
// httpRequest. The on-demand (fb-generate-now) path skips this node entirely.
const taken = new Set($('Get Existing Dates').all().map(i => i.json && i.json.scheduled_date).filter(Boolean));
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const buffer = Number($env.GENERATION_BUFFER_DAYS || 7);
const today = $now.toFormat('yyyy-LL-dd');
const until = $now.plus({ days: buffer }).toFormat('yyyy-LL-dd');
const planned = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_content_plan?status=eq.planned&plan_date=gte.' + today + '&plan_date=lte.' + until + '&select=id,plan_date,pillar,archetype,subtopic_id&order=plan_date.asc', headers: h, json: true });
const slot = (planned || []).find(s => !taken.has(s.plan_date));
if (slot) {
  let subtopic = null;
  if (slot.subtopic_id) {
    const rows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_subtopics?id=eq.' + slot.subtopic_id + '&select=id,subtopic,pillar,times_used', headers: h, json: true });
    subtopic = (rows && rows[0]) || null;
  }
  return [{ json: { scheduled_date: slot.plan_date, follow_plan: true, plan_id: slot.id, plan_pillar: slot.pillar, plan_archetype: slot.archetype, plan_subtopic_id: slot.subtopic_id || null, subtopic } }];
}
// Fallback: first open date within a 5-day horizon (original behaviour).
let target = null;
for (let i = 0; i < 5; i++) { const iso = $now.plus({ days: i }).toFormat('yyyy-LL-dd'); if (!taken.has(iso)) { target = iso; break; } }
if (!target) return [];               // horizon full -> emit nothing (no-op night)
return [{ json: { scheduled_date: target, follow_plan: false, plan_id: null } }];

// Merge subtopic + prompts + message bank into the generator system/user prompts.
// Prefer the planned slot's pillar/archetype/subtopic (nightly buffer top-up); otherwise the
// least-recently-used active subtopic + a date-derived archetype (also the on-demand path).
// Returns { system, user, subtopic_id, pillar, times_used, archetype, scheduled_date, plan_id }.
let picked = null; try { picked = $('Pick Plan Slot or Date').first().json; } catch (e) {}
const lru = $('Get LRU Subtopic').first().json;
const followPlan = !!(picked && picked.follow_plan);
const sub = (followPlan && picked.subtopic) ? picked.subtopic : lru;
const promptItems = $('Get Prompts + Bank').all();
const byName = Object.fromEntries(promptItems.map(i => [i.json.name, i.json.body]));
const bank = $('Get Message Bank').first()?.json?.variables ?? {};

const archetypes = ['myth-bust','secret-reveal','story','mistake-expose','seasonal','thought-leadership','community-cause','social-proof'];
const pillar = (followPlan && picked.plan_pillar) ? picked.plan_pillar : (sub.pillar || '');
const archetype = (followPlan && picked.plan_archetype) ? picked.plan_archetype : archetypes[new Date().getDate() % archetypes.length];

const user = (byName['generator'] || '')
  .replaceAll('{{style_guide}}', byName['style_guide'] || '')
  .replaceAll('{{message_bank}}', JSON.stringify(bank))
  .replaceAll('{{pillar}}', pillar)
  .replaceAll('{{archetype}}', archetype)
  .replaceAll('{{subtopic}}', sub.subtopic || '')
  // generator v2 also carries Strategist-brief placeholders. Until the Strategist pass is
  // wired, fill image-only / no-brief defaults, then strip any leftover placeholder tokens
  // so a literal one never reaches the model.
  .replaceAll('{{buyer_stage}}', '#1')
  .replaceAll('{{buyer_objective}}', 'education')
  .replaceAll('{{caption_direction}}', '')
  .replaceAll('{{media_type}}', 'image')
  .replaceAll('{{image_concept}}', '')
  .replaceAll('{{video_concept}}', '')
  .replaceAll('{{recommended_cta}}', 'soft: end with one engagement question')
  .replace(/\{\{[^}]+\}\}/g, '');

// scheduled_date comes from the webhook body (on-demand) or the picker (nightly).
let scheduled_date = null;
try { scheduled_date = $('On-demand (fb-generate-now)').first().json.body.scheduled_date; } catch (e) {}
if (!scheduled_date) { try { scheduled_date = picked.scheduled_date; } catch (e) {} }

return [{ json: {
  system: byName['style_guide'] || '',
  user,
  subtopic_id: sub.id,
  pillar,
  times_used: sub.times_used || 0,
  archetype,
  scheduled_date,
  plan_id: followPlan ? picked.plan_id : null
} }];

// Tolerant JSON parse: strip ```json fences, then JSON.parse; on failure extract
// the first balanced {...}. Returns the generator object { post_body, first_comment, image_concept, ... }.
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let out;
try { out = JSON.parse(t); } catch (e) {
  const m = t.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : {};
}
return [{ json: out }];

// Decode the base64 image returned by the provider and prepare it as binary for upload.
const b64 = $json.data?.[0]?.b64_json;
if (!b64) throw new Error('No image returned');
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.png`;
return [{ json: { path }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), path, 'image/png') } }];
